Lemma kword_byte : forall E (M : mem) a n v A z k b, kentry_ok RSEGS E M (KWord a n v) -> estart E a = A -> 0 <= A -> A + Z.of_nat n <= 2 ^ 64 ->
  bv_unsigned (edenot E v) = z -> (k < n)%nat -> (z / 2 ^ (8 * Z.of_nat k)) mod 256 = b -> forall A', A + Z.of_nat k = A' -> L5.u8_at RSEGS M A' b.
Proof.
  intros E M a n v A z k b (_ & Hfl & Hr) Ha H0 H1 Hz Hk Hb A' <-. rewrite <- Hb.
  pose proof (bv_unsigned_in_range _ (edenot E v)) as Rz. change (bv_modulus 64) with (2 ^ 64) in Rz.
  apply (TKX.wordn_lit_byte M n A z k H0 H1 ltac:(lia)); [|exact Hk].
  rewrite <- Ha, <- (CL5.adenot_start E a _ Hfl), Hr, <- Hz, Z_to_bv_bv_unsigned. reflexivity.
Qed.

Ltac cfind_in cs a n :=
  lazymatch cs with
  | KWord a n ?v :: _ => v
  | _ :: ?rest => cfind_in rest a n
  end.
Ltac cfind HLF a n :=
  lazymatch type of HLF with CC.leaf_facts _ _ ?ps _ _ _ _ =>
    let cs := eval vm_compute in (SR.ps_cells ps) in cfind_in cs a n end.
Ltac gval := first [ reflexivity | cbn [edenot]; rw_atoms; reflexivity
  | apply CL5.u_lin; [lin_eval; rw_atoms; rewrite ?u64_of_Z by lia; lia | lia] ].
Ltac gcell HLF b off n v := exact (CK.lf_cell _ _ _ _ _ _ (KWord (SA b off) n v) HLF ltac:(vm_compute; reflexivity)).
Ltac g64 HLF b off := let v := cfind HLF (SA b off) 8%nat in
  eapply (CL5.kword64_elim RSEGS _ _ (SA b off) v); [gcell HLF b off 8%nat v | ev_start | gval].
Ltac g32 HLF b off := let v := cfind HLF (SA b off) 4%nat in
  eapply (TK.kword32_elim _ _ (SA b off) v); [gcell HLF b off 4%nat v | ev_start | gval].
Ltac g8 HLF b off := let v := cfind HLF (SA b off) 1%nat in
  eapply (RK.kword8_elim _ _ (SA b off) v); [gcell HLF b off 1%nat v | ev_start | gval].
Ltac gbyte HLF b off n k := let v := cfind HLF (SA b off) n in
  eapply (kword_byte _ _ (SA b off) n v _ _ k); [gcell HLF b off n v | ev_start | lia | lia | gval | lia | vm_compute; reflexivity | lia].

