Lemma getr_lit : forall (R : bvmap 5 word) (q : nat) (r : reg), Z_to_bv 5 (Z.of_nat q) = r -> getr R (Z_to_bv 5 (Z.of_nat q)) = getr R r.
Proof. intros R q r <-. reflexivity. Qed.
