  [ match goal with P : L5.u64_at _ _ ?A ?z |- kentry_ok _ _ _ (KWord _ 8 _) => ck_kw64 A z P end
  | match goal with P : L5.u8_at _ _ ?A ?z |- kentry_ok _ _ _ (KWord _ 1 _) => ck_kw8 A z P end ].
Lemma and240_den : forall E rb, bv_unsigned (ev E 66) = rb -> 0 <= rb < 2 ^ 64 -> edenot E (EAlu ALU_AND (EVar 66) (ELit 240)) = Z_to_bv 64 (Z.land rb 240).
Proof. intros E rb U Hr. cbn [edenot]. rewrite (RK.w_of_u _ _ U). apply RK.and_lit; lia. Qed.
Ltac kand := match goal with P : L5.u8_at _ _ ?A0 (Z.land ?rb0 240) |- kentry_ok _ _ _ (KWord _ 1 (EAlu ALU_AND _ (ELit 240))) =>
  match goal with U : bv_unsigned (ev _ 66) = rb0 |- _ =>
  eapply TK.kword8_intro with (A := A0) (z := Z.land rb0 240); [ev_start | lia | lia | exact (and240_den _ rb0 U ltac:(lia)) | pose proof (land240_range rb0); lia | exact P] end end.
Ltac kzero := match goal with P : RCS.zeros _ ?A0 ?N0 |- kentry_ok _ _ _ (KZero _ _) =>
  eapply RCS.kzero_intro with (A := A0) (N := N0); [ev_start | reflexivity | lia | lia | lia | lia | exact P] end.
Ltac gand HLF off := eapply (RK.kword8_elim _ _ (SA (EVar 2) off) (EAlu ALU_AND (EVar 66) (ELit 240)));
  [gcell HLF (EVar 2) off 1%nat (EAlu ALU_AND (EVar 66) (ELit 240)) | ev_start |];
  cbn [edenot]; match goal with U : bv_unsigned (ev _ 66) = ?rb |- _ => rewrite (RK.w_of_u _ _ U), RK.and_lit by lia; apply u64_of_Z; pose proof (land240_range rb); lia end.
Ltac gz0 HLF b off n := exact (CK.lf_cell _ _ _ _ _ _ (KZero (SA b off) (ELit n)) HLF ltac:(vm_compute; reflexivity)).

