Lemma s_ec_b : forall (fx : FPState) R M model K sp1 V SKT rb g1 g2 a2v R0,
  m_halted model = None -> m_vm_lazy model = [] -> PML.fp_ok fx ->
  getr R 2%bv = Z_to_bv 64 (sp1 - 336) -> CK.spok sp1 -> getr R 8%bv = Z_to_bv 64 (sp1 - 264) -> getr R 9%bv = Z_to_bv 64 (V + 16) -> getr R 18%bv = Z_to_bv 64 (V + 80) ->
  2 ^ 40 <= V <= 2 ^ 47 - 408 -> V mod 8 = 0 -> 2 ^ 40 <= SKT <= 2 ^ 47 - 8 -> 0 <= rb < 2 ^ 64 -> 0 <= g1 < 2 ^ 64 -> 0 <= g2 < 2 ^ 64 -> 0 <= a2v < 2 ^ 64 ->
  PML.img_ro M -> ec_frame M sp1 R0 -> L5.ra_ok (bv_unsigned (getr R0 1%bv)) -> junctA M sp1 V SKT rb g1 g2 a2v ->
  L5.defined M (sp1 - 400) 400 -> L5.defined M V 408 -> sp1 <= V -> sp1 <= SKT -> PML.apart V 408 SKT 8 ->
