      [vm_compute; reflexivity | lia | lia | exact H2 |].
    intros q e X. fold E. cbn [In] in X. destruct X as [X|[X|[X|[]]]]; injection X as <- <-.
    + rewrite (getr_lit R 8 8%bv) by (apply bv_eq; reflexivity). rewrite H8. symmetry. apply TK.edenot_lin; [lin_eval; rw_atoms; lia | lia].
