    + rewrite (getr_lit R 18 18%bv) by (apply bv_eq; reflexivity). rewrite H18. symmetry. apply TK.edenot_lin; [lin_eval; rw_atoms; lia | lia].
  - unfold know_ok, GB.cp0. cbn [CC.cp_know]. repeat (apply Forall_cons); [.. | apply Forall_nil].
