    pose proof (CC.lf_grows _ _ _ _ _ _ _ HLF) as MG.
    apply (CK.ret_leaf fx' R' _ M' model K (bv_unsigned (getr R0 1%bv)) ret_ec Hh Hl); [tk_lin HLF (1%bv : reg) | exact Hra |].
    apply (Hcont fx' R' M' Hfp'); [tk_lin HLF (2%bv : reg) | | | | ck_keeps HLF Hag64 KOA | | | ].
    + tk_reg HLF (8%bv : reg). match goal with U : bv_unsigned (ev E' 70) = _ |- _ => rewrite (RK.w_of_u _ _ U) end. apply Z_to_bv_bv_unsigned.
    + tk_reg HLF (9%bv : reg). match goal with U : bv_unsigned (ev E' 71) = _ |- _ => rewrite (RK.w_of_u _ _ U) end. apply Z_to_bv_bv_unsigned.
