      split; [g64 HLF (EVar 64) 264|]. split; [g64 HLF (EVar 64) 272|]. split; [g64 HLF (EVar 64) 280|]. split; [g32 HLF (EVar 64) 288|].
      split; [eapply RCS.kzero_elim; [gz0 HLF (EVar 64) 296 8 | ev_start | reflexivity]|].
      split; [g64 HLF (EVar 64) 304|]. split; [g64 HLF (EVar 64) 312|]. split; [g64 HLF (EVar 64) 320|]. split; [g64 HLF (EVar 64) 328|].
      split; [g64 HLF (EVar 64) 336|]. split; [g64 HLF (EVar 64) 344|]. split; [g64 HLF (EVar 64) 352|]. split; [g64 HLF (EVar 64) 360|].
