Ltac cp8 M M' a b w k G C B := lazymatch goal with |- L5.u8_at _ _ ?A _ =>
  replace A with (b + k) by lia;
  apply (SBC.u64_copy_u8 M M' a b w k); [lia | lia | lia | lia | exact G | exact C | lia |
    lazymatch type of B with L5.u8_at _ _ ?A1 _ => replace (a + k) with A1 by lia; exact B end] end.
Ltac hyp_at := match goal with
  | H : L5.u64_at _ ?M ?A' _ |- L5.u64_at _ ?M ?A _ => replace A with A' by lia; exact H
  | H : L5.u32_at _ ?M ?A' _ |- L5.u32_at _ ?M ?A _ => replace A with A' by lia; exact H
  | H : L5.u8_at _ ?M ?A' _ |- L5.u8_at _ ?M ?A _ => replace A with A' by lia; exact H end.

