Theorem enc_ctor_ok : PMES.enc_ctor_spec L HI.
Proof.
  unfold PMES.enc_ctor_spec, PML.cps_heap.
  intros LB cr sp r V S2 SKT fx R M model K HH (Hh & Hl & Hmat) HK0 Hfp
    (EN & A0 & A1 & SK0 & DSK & SNK & DV & ((OV1 & OV2 & OV3) & (OS1 & OS2 & OS3) & APVS) & (OK1 & OK2 & OK3) & APK & APS & RO & LQ) Hcont.
  destruct EN as (Hra & Hrok & Hsp & Htp & STK). pose proof STK as (S1 & S2' & S3 & S4 & S5).
  unfold PML.a0, PML.a1, PML.apart, PML.u64, PMES.ENC_SIZE in *.
  pose proof (PmLayout.ly_img_lo L LAY) as ILO. pose proof (PmLayout.ly_img_hi L LAY) as IHI.
  set (SCR := PMES.ENC_CTOR_SCR) in *.
  let v := eval vm_compute in PMES.ENC_CTOR_SCR in assert (HSCR : SCR = v) by reflexivity.
  assert (SPOK : CK.spok sp) by (split; [unfold hl_ceil in *; lia | exact S1]).
  pose proof (TK2.blocks_ok_heap L HI HIok _ _ _ _ HH) as BOK.
  assert (Hr64 : 0 <= r < 2 ^ 64) by (destruct Hrok; lia).
  assert (UR1 : bv_unsigned (getr R 1%bv) = r) by (rewrite Hra; apply u64_of_Z; lia).
  assert (APVK : PML.apart V 408 SKT 8) by (unfold PML.apart; lia).
  assert (DS400 : L5.defined M (sp - 400) 400) by (eapply L5.defined_sub; [exact S5 | lia | lia]).
  pose proof (bv_unsigned_in_range _ (getr R 12%bv)) as A2R. change (bv_modulus 64) with (2 ^ 64) in A2R.
  apply (s_ec_a FPM fx R M model K sp V SKT S2 Hh Hl Hfp Hsp SPOK A0 A1 ltac:(lia) OV3 ltac:(lia) ltac:(lia) RO SK0 DSK DV DS400 ltac:(lia) ltac:(lia) APVK).
  intros fx1 R1 M1 Hfp1 H2a H8a H9a H18a KO1 EF1 (rb & g1 & g2 & Rrb & Rg1 & Rg2 & J1) CA1 AG1 MG1.
  assert (RO1 : PML.img_ro M1) by (apply (TK.img_clear_samem _ M M1 _ _ AG1); [lia | unfold PML.IMG_RO_HI; lia | intros i Hi; unfold PML.IMG_RO_HI in Hi; cbv beta; lia | exact RO]).
  apply (s_ec_b FPM fx1 R1 M1 model K sp V SKT rb g1 g2 (bv_unsigned (getr R 12%bv)) R Hh Hl Hfp1 H2a SPOK H8a H9a H18a ltac:(lia) OV3 ltac:(lia) Rrb Rg1 Rg2 A2R RO1 EF1
    ltac:(rewrite UR1; exact Hrok) J1 (L5.defined_grows _ _ _ _ MG1 DS400) (L5.defined_grows _ _ _ _ MG1 DV) ltac:(lia) ltac:(lia) APVK).
  intros fx2 R2 M2 Hfp2 H2b H8b H9b H18b KO2 CB2 AG2 MG2.
  rewrite UR1.
  set (K02 := fun a : Z => ~ (sp - 400 <= a < sp) /\ ~ (V <= a < V + 408) /\ ~ (SKT <= a < SKT + 8)).
  assert (AG02 : TK.samem K02 M M2) by (apply (CK.samem_weaken2 _ _ _ M M1 M2 AG1 AG2); intros a Ha; unfold K02 in Ha; cbv beta in *; lia).
  assert (MG02 : mem_grows M M2) by (intros z Hz; apply MG2, MG1; exact Hz).
  set (K2 := fun a : Z => ~ (sp - 400 <= a < sp) /\ ~ (V + 24 <= a < V + 40) /\ ~ (V + 48 <= a < V + 80) /\ ~ (V + 248 <= a < V + 408)) in AG2.
  unfold junctA in J1. destruct J1 as (J312 & J320 & J328 & J336 & J280 & J288 & J296 & J304 & B256 & B255 & B254 & B253 & B252 & B251 & B250 & B249 & B248 & B247 & B246 & B245 & B244
    & B232 & B231 & B230 & B229 & B228 & B227 & B226 & B225 & J224 & J216 & B208 & JZ & G1s & G2s).
  unfold cellsA in CA1. destruct CA1 as (A0v & A8 & A16 & A40 & A80 & (en & Aen & Hen) & A240 & O96 & O120 & O144 & O168 & O192 & O216 & ASKT).
  unfold cellsB in CB2. destruct CB2 as (C24 & C32 & C48 & C56 & C64 & C72 & C248 & C252 & C256 & C260 & C264 & C272 & C280 & C288 & C296 & C304 & C312 & C320 & C328
    & C336 & C344 & C352 & C360 & C368 & C376 & C384 & C392 & C400 & D256 & D253 & D252 & D251 & D250 & D249 & D248 & D244).
  apply (Hcont fx2 R2 M2 model LB cr LB [(V, 408); (SKT, 8)] Hfp2).
  - cbv beta. split; [|split; [|split; [|repeat split]]].
    + unfold PMES.enc_inv, PMES.g0. cbn [PMES.g_es PMES.g_sb PMES.g_scap PMES.g_rep PMES.g_len].
      change (PMES.depth []) with 0.
      split; [|split; [|split; [|split]]].
      * unfold PMES.enc_obj, PMES.sv_at, PMES.O_SINK, PMES.O_OPT_VPTR, PMES.O_FLAGS, PMES.O_BIGNUM_FMT, PMES.O_SPLITS, PMES.O_INDENT_SIZE, PMES.O_LINE_LIMIT,
          PMES.O_NL_CHARS, PMES.O_COMMON_VPTR, PMES.O_ENABLE, PMES.O_MAX_DEPTH, PMES.O_INDENT_CHAR, PMES.O_FP, PMES.O_INDENT, PMES.O_COLUMN, PMES.O_DEPTH,
          PMES.O_COLON, PMES.O_COMMA, PMES.O_OBRACE, PMES.O_CBRACE, PMES.O_OBRACKET, PMES.O_CBRACKET, PML.u64, PML.u8, PML.u32.
        split; [tr64 K2 M1 M2 AG2 A0v|]. split; [tr64 K2 M1 M2 AG2 A8|]. split; [tr64 K2 M1 M2 AG2 A16|].
        split.
        { exists (Z.land rb 240). split; [cp8 M1 M2 (sp - 256) (V + 24) g1 0 G1s C24 B256|].
          rewrite <- Z.land_assoc. change (Z.land 240 15) with 0. apply Z.land_0_r. }
        split; [cp8 M1 M2 (sp - 256) (V + 24) g1 3 G1s C24 B253|]. split; [cp8 M1 M2 (sp - 256) (V + 24) g1 4 G1s C24 B252|].
        split; [cp8 M1 M2 (sp - 256) (V + 24) g1 5 G1s C24 B251|]. split; [cp8 M1 M2 (sp - 256) (V + 24) g1 6 G1s C24 B250|].
        split; [cp8 M1 M2 (sp - 256) (V + 24) g1 7 G1s C24 B249|]. split; [cp8 M1 M2 (sp - 248) (V + 32) g2 0 G2s C32 B248|].
        split; [cp8 M1 M2 (sp - 248) (V + 32) g2 4 G2s C32 B244|].
        split; [tr64 K2 M1 M2 AG2 A40|].
        split; [hyp_at|]. split; [hyp_at|]. split; [hyp_at|].
        split; [apply (L5.defined_grows _ _ _ _ MG02); eapply L5.defined_sub; [exact DV | lia | lia]|].
        split; [tr64 K2 M1 M2 AG2 A80|].
        split.
        { exists en. split; [tr8 K2 M1 M2 AG2 Aen|]. split; [exact Hen|]. apply (L5.defined_grows _ _ _ _ MG02). eapply L5.defined_sub; [exact DV | lia | lia]. }
        split; [tr32 K2 M1 M2 AG2 A240|]. split; [hyp_at|]. split; [hyp_at|]. split; [hyp_at|].
        split; [exists 46; hyp_at|].
        split; [hyp_at|].
        split; [apply (L5.defined_grows _ _ _ _ MG02); eapply L5.defined_sub; [exact DV | lia | lia]|].
        split; [apply TKX.u32_zero; exact C400|].
        repeat split; hyp_at.
      * unfold PMES.stack_at, PMES.O_STACK, PML.u64. split; [hyp_at|]. split; [hyp_at|]. split; [hyp_at|].
        split; [unfold PMES.depth; cbn; lia|]. split; [left; split; reflexivity|]. intros i Hi. cbn in Hi. lia.
      * apply (EK.sink_at_agree M M2 S2 (PML.SShort [])); [lia | lia | | exact I | exact SNK].
        apply (TKX.agree_of_samem K02 M M2 S2 24 AG02); [lia | lia | intros i Hi; unfold K02; cbv beta; lia].
      * reflexivity.
      * unfold PMES.depth, PMES.MAX_DEPTH. cbn. lia.
    + apply (TKX.opts_idle_x K2 M1 M2 V AG2); [lia | unfold PMES.ENC_SIZE; lia | intros i Hi; unfold K2; cbv beta; lia | unfold PMES.opts_idle; repeat split; assumption].
    + tr64 K2 M1 M2 AG2 ASKT.
  - apply rp_final; [rewrite H2b, Hsp; reflexivity | exact H8b | exact H9b | exact H18b | exact (TK.keepsR_trans _ _ _ _ KO1 KO2)].
  - set (foot := fun a : Z => V <= a < V + 408 \/ SKT <= a < SKT + 8).
    assert (FR0 : TK2.FR L LB sp SCR foot M M) by (split; [intros a _ _ _ _; reflexivity | intros a Ha; replace a with (sp - SCR + (a - (sp - SCR))) by lia; apply S5; lia]).
    assert (FR2 : TK2.FR L LB sp SCR foot M M2).
    { apply (TK2.FR_grows L LAY LB sp SCR foot M M M2 _ FR0 AG02 MG02 BOK ltac:(unfold hl_ceil in *; lia) ltac:(lia)). intros a Ha. unfold K02, foot in *. cbv beta in *. lia. }
    destruct FR2 as [F1 F2]. apply L5C.hpres_intro.
    + intros a (Ha & HC & HE & HO). apply F1; [exact Ha | exact HC | | exact HE]. unfold foot. intros [X|X].
      * apply (HO (V, 408) (or_introl eq_refl)). unfold L5.in_rng. cbn [fst snd]. exact X.
      * apply (HO (SKT, 8) (or_intror (or_introl eq_refl))). unfold L5.in_rng. cbn [fst snd]. exact X.
    + intros i Hi. apply F2. lia.
    + intros a Ha HC HE Hd. destruct (classic (foot a)) as [Y|N]; [apply MG02; exact Hd | rewrite (F1 a Ha HC N HE); exact Hd].
  - apply L5C.model_but_vm_refl.
  - apply (TK2.heap_stack_write L HI HIok LAY _ _ M M2 _ (sp - 400) (hl_sptop L) HH ltac:(lia) ltac:(unfold hl_ceil in *; lia) ltac:(lia)); [|exact MG02].
    apply (TK.samem_weaken _ _ _ _ AG02). intros a Ha. unfold K02. cbv beta in *. lia.
Qed.
End H.
End ECX.
